import{_ as o,a0 as n,w as r,s as p,I as s,x as e,a1 as a,A as d,ao as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"systemd 日誌維護指南（附實例） | LCTT x X-CMD","titleTemplate":false,"description":"systemd 日誌維護指南（附實例） | LCTT (202302) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"systemd 日誌維護指南（附實例） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"systemd 日誌維護指南（附實例） | LCTT (202302) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202302/20221109.3 ⭐️⭐️ A Guide to systemd journal Maintenance [With Examples]","title":"systemd 日誌維護指南（附實例）","tag":"202302","desc":""},"relativePath":"202302/20221109.3 ⭐️⭐️ A Guide to systemd journal Maintenance [With Examples].md","filePath":"[post].md"}'),u={name:"202302/20221109.3 ⭐️⭐️ A Guide to systemd journal Maintenance [With Examples].md"};function g(h,t,m,c,f,y){const l=n("Link");return r(),p("div",null,[t[32]||(t[32]=s("h1",{id:"systemd-日誌維護指南-附實例",tabindex:"-1"},[e("systemd 日誌維護指南（附實例） "),s("a",{class:"header-anchor",href:"#systemd-日誌維護指南-附實例","aria-label":"Permalink to “systemd 日誌維護指南（附實例）”"},"​")],-1)),t[33]||(t[33]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202302/10/072955z20ipg8vlpvdt1jq.jpg",alt:""})],-1)),t[34]||(t[34]=s("blockquote",null,[s("p",null,"systemd 內置了很多管理系統日誌的功能。在本指南中，我們將介紹如何管理系統日誌，並對其採取輪換、歸檔和清除日誌等操作。我們還解釋了手動系統日誌清理方法和使用配置文件的變化。")],-1)),s("p",null,[t[1]||(t[1]=e("如果你的 Linux 發行版支持 ",-1)),a(l,{href:"https://www.freedesktop.org/wiki/Software/systemd/"},{default:d(()=>[...t[0]||(t[0]=[e("systemd",-1)])]),_:1}),t[2]||(t[2]=e("，那麼從啓動時開始，它每秒鐘都會從系統的所有進程和應用程序中收集日誌。所有這些日誌事件都由 systemd 的 ",-1)),t[3]||(t[3]=s("code",null,"journald",-1)),t[4]||(t[4]=e(" 守護程序管理。journald 收集所有的日誌（信息、警告、錯誤等），並將其作為二進制數據存儲在磁盤文件中。",-1))]),t[35]||(t[35]=s("p",null,"由於日誌保留在磁盤中，而且每秒鐘都在收集，所以它佔用了巨大的磁盤空間；特別是對於舊的系統、服務器來説。例如，在我的一個運行了一年左右的測試系統中，日誌文件的大小是 GB 級的。",-1)),t[36]||(t[36]=s("p",null,"如果你管理多個系統、服務器，建議一定要正確管理 journald 日誌，以便高效運行。讓我們來看看如何管理日誌文件。",-1)),t[37]||(t[37]=s("h3",{id:"systemd-日誌維護",tabindex:"-1"},[e("systemd 日誌維護 "),s("a",{class:"header-anchor",href:"#systemd-日誌維護","aria-label":"Permalink to “systemd 日誌維護”"},"​")],-1)),s("p",null,[t[6]||(t[6]=e("使用 systemd 的 ",-1)),t[7]||(t[7]=s("code",null,"journalctl",-1)),t[8]||(t[8]=e(" 工具，你可以查詢這些日誌，對其進行各種操作。例如，查看不同啓動時的日誌文件，檢查特定進程或應用程序的最後警告和錯誤。如果你對這些不瞭解，我建議你在學習本指南之前先快速瀏覽一下此教程：",-1)),a(l,{href:"https://www.debugpoint.com/2020/12/systemd-journalctl/"},{default:d(()=>[...t[5]||(t[5]=[e("使用 journalctl 查看和分析 systemd 日誌（附實例）",-1)])]),_:1}),t[9]||(t[9]=e(" 》。",-1))]),t[38]||(t[38]=i('<h4 id="物理日記的日誌文件在哪裏" tabindex="-1">物理日記的日誌文件在哪裏？ <a class="header-anchor" href="#物理日記的日誌文件在哪裏" aria-label="Permalink to “物理日記的日誌文件在哪裏？”">​</a></h4><p>systemd 的 journald 守護進程在每次啓動時都會收集日誌。這意味着，它根據啓動情況對日誌文件進行分類。</p><p>日誌以二進制形式存儲在路徑 <code>/var/log/journal</code>，文件夾為機器 ID。</p><p>比如説：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/Screenshot-of-physical-journal-file-1.jpg" alt="日誌文件位置的截圖-1"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/Screenshot-of-physical-journal-files-2.jpg" alt="日誌文件位置的截圖-2"></p><p>另外，請記住，根據系統配置，運行時日誌文件被存儲在 <code>/run/log/journal/</code>。而這些在每次啓動時都會被刪除。</p><h4 id="我可以手動刪除日誌文件嗎" tabindex="-1">我可以手動刪除日誌文件嗎？ <a class="header-anchor" href="#我可以手動刪除日誌文件嗎" aria-label="Permalink to “我可以手動刪除日誌文件嗎？”">​</a></h4><p>你可以，但不要這樣做。相反，請按照下面的説明，使用 <code>journalctl</code> 工具清除日誌文件以釋放磁盤空間。</p><h4 id="systemd-的日誌文件佔用了多少磁盤空間" tabindex="-1">systemd 的日誌文件佔用了多少磁盤空間？ <a class="header-anchor" href="#systemd-的日誌文件佔用了多少磁盤空間" aria-label="Permalink to “systemd 的日誌文件佔用了多少磁盤空間？”">​</a></h4><p>打開一個終端，運行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl --disk-usage</span></span></code></pre></div><p>這應該為你提供系統中的日誌文件實際使用的數量。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/journalctl-disk-usage-command.jpg" alt="journalctl 磁盤使用命令"></p><p>如果你有一個圖形化的桌面環境，你可以打開文件管理器，瀏覽路徑 <code>/var/log/journal</code>，並檢查屬性。</p><h4 id="systemd-日誌清理過程" tabindex="-1">systemd 日誌清理過程 <a class="header-anchor" href="#systemd-日誌清理過程" aria-label="Permalink to “systemd 日誌清理過程”">​</a></h4><p>清理日誌文件的有效方法應該是通過 <code>journald.conf</code> 配置文件來完成。正常情況下，即使 <code>journalctl</code> 提供了刪除日誌文件的工具，你也不應該手動刪除這些文件。</p>',17)),s("p",null,[t[11]||(t[11]=e("讓我們來看看如何 ",-1)),a(l,{href:"https://www.debugpoint.com#delete-using-journal-conf"},{default:d(()=>[...t[10]||(t[10]=[e("手動",-1)])]),_:1}),t[12]||(t[12]=e(" 刪除它，然後我將解釋 ",-1)),t[13]||(t[13]=s("code",null,"journald.conf",-1)),t[14]||(t[14]=e(" 中的配置變化，這樣你就不需要時不時地手動刪除文件；相反，systemd 會根據你的配置自動處理它。",-1))]),t[39]||(t[39]=i('<h5 id="手動刪除" tabindex="-1">手動刪除 <a class="header-anchor" href="#手動刪除" aria-label="Permalink to “手動刪除”">​</a></h5><p>首先，你必須 <code>flush</code> 和 <code>rotate</code> 日誌文件。<ruby>輪換<rt>rotate</rt></ruby>是將當前活動的日誌文件歸檔，並立即開始創建一個新的日誌文件繼續記錄日誌。<ruby>沖洗<rt>flush</rt></ruby> 開關要求日誌守護進程將存儲在 <code>/run/log/journal/</code> 中的所有日誌數據衝入 <code>/var/log/journal/</code>，如果持久性存儲被啓用的話。</p><p>然後，在 <code>flush</code> 和 <code>rotate</code> 之後，你需要用 <code>vacuum-size</code>、<code>vacuum-time</code> 和 <code>vacuum-files</code> 選項運行 <code>journalctl</code> 來強制 systemd 清除日誌。</p><p>例 1：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --flush --rotate</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --vacuum-time=1s</span></span></code></pre></div><p>上面這組命令會刪除所有存檔的日誌文件，直到最後一秒。這有效地清除了一切。因此，在運行該命令時要小心。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/journal-clean-up-example.jpg" alt="日誌清理-例子"></p><p>清理完畢後：</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/After-clean-up-journal-space-usage.jpg" alt="清理後--日誌的佔用空間"></p><p>你也可以根據你的需要在 <code>--vacuum-time</code> 的數字後面提供以下後綴：</p><ul><li><code>s</code>：秒</li><li><code>m</code>：分鐘</li><li><code>h</code>：小時</li><li><code>days</code>：天</li><li><code>months</code>：月</li><li><code>weeks</code>：周</li><li><code>years</code>：年</li></ul><p>例 2：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --flush --rotate</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --vacuum-size=400M</span></span></code></pre></div><p>這將清除所有存檔的日誌文件，並保留最後 400MB 的文件。記住這個開關只適用於存檔的日誌文件，不適用於活動的日誌文件。你也可以使用後綴，如下所示。</p><ul><li><code>K</code>：KB</li><li><code>M</code>：MB</li><li><code>G</code>：GB</li></ul><p>例 3：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --flush --rotate</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo journalctl --vacuum-files=2</span></span></code></pre></div><p><code>vacuum-files</code> 選項會清除所有低於指定數量的日誌文件。因此，在上面的例子中，只有最後兩個日誌文件被保留，其他的都被刪除。同樣，這隻對存檔的文件有效。</p><p>如果你願意，你可以把兩種選項結合起來，但我建議不要這樣做。然而，如果同時使用兩個選項，請確保先用 <code>--rotate</code> 選項運行。</p><h3 id="使用配置文件自動刪除" tabindex="-1">使用配置文件自動刪除 <a class="header-anchor" href="#使用配置文件自動刪除" aria-label="Permalink to “使用配置文件自動刪除”">​</a></h3><p>雖然上述方法很好，也很容易使用，但建議你使用 journald 配置文件來控制日誌文件的清理過程，該文件存在於 <code>/etc/systemd/journald.conf</code>。</p><p>systemd 為你提供了許多參數來有效管理日誌文件。通過組合這些參數，你可以有效地限制日誌文件所佔用的磁盤空間。讓我們來看看。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">journald.conf 參數</th><th style="text-align:left;">描述</th><th style="text-align:left;">實例</th></tr></thead><tbody><tr><td style="text-align:left;"><code>SystemMaxUse</code></td><td style="text-align:left;">指定日誌在持久性存儲中可使用的最大磁盤空間</td><td style="text-align:left;"><code>SystemMaxUse=500M</code></td></tr><tr><td style="text-align:left;"><code>SystemKeepFree</code></td><td style="text-align:left;">指定在將日誌條目添加到持久性存儲時，日誌應留出的空間量。</td><td style="text-align:left;"><code>SystemKeepFree=100M</code></td></tr><tr><td style="text-align:left;"><code>SystemMaxFileSize</code></td><td style="text-align:left;">控制單個日誌文件在被輪換之前在持久性存儲中可以增長到多大。</td><td style="text-align:left;"><code>SystemMaxFileSize=100M</code></td></tr><tr><td style="text-align:left;"><code>RuntimeMaxUse</code></td><td style="text-align:left;">指定在易失性存儲中可以使用的最大磁盤空間（在 <code>/run</code> 文件系統內）。</td><td style="text-align:left;"><code>RuntimeMaxUse=100M</code></td></tr><tr><td style="text-align:left;"><code>RuntimeKeepFree</code></td><td style="text-align:left;">指定將數據寫入易失性存儲（在 <code>/run</code> 文件系統內）時為其他用途預留的空間數量。</td><td style="text-align:left;"><code>RuntimeMaxUse=100M</code></td></tr><tr><td style="text-align:left;"><code>RuntimeMaxFileSize</code></td><td style="text-align:left;">指定單個日誌文件在被輪換之前在易失性存儲（在 <code>/run</code> 文件系統內）所能佔用的空間量。</td><td style="text-align:left;"><code>RuntimeMaxFileSize=200M</code></td></tr></tbody></table></div><p>如果你在運行中的系統的 <code>/etc/systemd/journald.conf</code> 文件中添加這些值，那麼在更新文件後，你必須重新啓動 journald。要重新啓動，請使用以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl restart systemd-journald</span></span></code></pre></div><h3 id="核實日誌文件" tabindex="-1">核實日誌文件 <a class="header-anchor" href="#核實日誌文件" aria-label="Permalink to “核實日誌文件”">​</a></h3><p>在你清理完文件後，檢查日誌文件的完整性是比較明智的。要做到這一點，請運行下面的命令。該命令顯示了日誌文件是否通過（<code>PASS</code>）、失敗（<code>FAIL</code>）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>journalctl --verify</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/01/verify-log-files.png" alt="驗證日誌文件"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>希望本指南能幫助你瞭解 systemd 日誌管理流程的基本情況。通過這些，你可以通過限制空間、清除舊的日誌文件來管理系統或服務器中的日誌文件所使用的磁盤空間。這些只是指導性的命令，你可以通過多種方式組合這些命令來實現你的系統需求。</p>',34)),s("ul",null,[s("li",null,[a(l,{href:"https://www.freedesktop.org/software/systemd/man/journalctl.html"},{default:d(()=>[...t[15]||(t[15]=[e("journalctl 手冊",-1)])]),_:1})]),s("li",null,[a(l,{href:"https://www.freedesktop.org/software/systemd/man/journald.conf.html"},{default:d(()=>[...t[16]||(t[16]=[e("journald.conf 手冊",-1)])]),_:1})])]),t[40]||(t[40]=s("hr",null,null,-1)),s("p",null,[t[18]||(t[18]=e("via: ",-1)),a(l,{href:"https://www.debugpoint.com/systemd-journald-clean/"},{default:d(()=>[...t[17]||(t[17]=[e("https://www.debugpoint.com/systemd-journald-clean/",-1)])]),_:1})]),s("p",null,[t[23]||(t[23]=e("作者：",-1)),a(l,{href:"https://www.debugpoint.com/author/admin1/"},{default:d(()=>[...t[19]||(t[19]=[e("Arindam",-1)])]),_:1}),t[24]||(t[24]=e(" 選題：",-1)),a(l,{href:"https://github.com/lkxed"},{default:d(()=>[...t[20]||(t[20]=[e("lkxed",-1)])]),_:1}),t[25]||(t[25]=e(" 譯者：",-1)),a(l,{href:"https://github.com/Chao-zhi"},{default:d(()=>[...t[21]||(t[21]=[e("Chao-zhi",-1)])]),_:1}),t[26]||(t[26]=e(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:d(()=>[...t[22]||(t[22]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[29]||(t[29]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[27]||(t[27]=[e("LCTT",-1)])]),_:1}),t[30]||(t[30]=e(" 原創編譯，",-1)),a(l,{href:"https://linux.cn/"},{default:d(()=>[...t[28]||(t[28]=[e("Linux中國",-1)])]),_:1}),t[31]||(t[31]=e(" 榮譽推出",-1))])])}const w=o(u,[["render",g]]);export{x as __pageData,w as default};
